	private void assertFedxMemberDoesNotContactPrivateTarget(boolean remoteRepository, boolean dataConfig)
			throws Exception {
		AtomicInteger privateRequests = new AtomicInteger();
		HttpServer privateEndpoint = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		privateEndpoint.createContext("/", exchange -> {
			privateRequests.incrementAndGet();
			byte[] body = "{\"head\":{},\"boolean\":false}".getBytes(StandardCharsets.UTF_8);
			exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+json");
			exchange.sendResponseHeaders(200, body.length);
			try (var output = exchange.getResponseBody()) {
				output.write(body);
			}
		});
		privateEndpoint.start();
		String repositoryId = dataConfig ? "managed-egress-fedx-file"
				: remoteRepository ? "managed-egress-fedx-remote" : "managed-egress-fedx-sparql";
		RemoteRepositoryManager manager = RemoteRepositoryManager.getInstance(TestServer.SERVER_URL);
		try {
			String baseUrl = "http://127.0.0.1:" + privateEndpoint.getAddress().getPort();
			Model members = new TreeModel();
			BNode member = Values.bnode();
			if (remoteRepository) {
				members.add(member, Vocabulary.FEDX.STORE, Values.literal("RemoteRepository"));
				members.add(member, Vocabulary.FEDX.REPOSITORY_SERVER, Values.literal(baseUrl));
				members.add(member, Vocabulary.FEDX.REPOSITORY_NAME, Values.literal("private"));
			} else {
				members.add(member, Vocabulary.FEDX.STORE, Values.literal("SPARQLEndpoint"));
				members.add(member, Vocabulary.SD.ENDPOINT, Values.iri(baseUrl + "/sparql"));
			}
			FedXRepositoryConfig fedx = new FedXRepositoryConfig();
			if (dataConfig) {
				fedx.setDataConfig("members.ttl");
				Path memberFile = server.managedRepositoryDirectory(repositoryId).toPath().resolve("members.ttl");
				Files.createDirectories(memberFile.getParent());
				try (var output = Files.newOutputStream(memberFile)) {
					Rio.write(members, output, RDFFormat.TURTLE);
				}
			} else {
				fedx.setMembers(members);
			}
			manager.addRepositoryConfig(new RepositoryConfig(repositoryId, fedx));
			HTTPRepository managed = new HTTPRepository(
					Protocol.getRepositoryLocation(TestServer.SERVER_URL, repositoryId));
			Throwable failure = catchThrowable(() -> {
				try (RepositoryConnection connection = managed.getConnection()) {
					connection.prepareBooleanQuery("ASK { ?s ?p ?o }").evaluate();
				}
			});
			assertThat(privateRequests).as("Server must not contact an untrusted FedX member")
					.hasValue(0);
			if (remoteRepository) {
				assertThat(failure).hasStackTraceContaining("could not read protocol version from server");
				assertThat(server.serverRepositoryFailure(repositoryId, "ASK { ?s ?p ?o }"))
						.hasStackTraceContaining("Remote RDF resource denied");
				assertThat(privateRequests).hasValue(0);
			} else {
				assertThat(failure).hasStackTraceContaining("Remote RDF resource denied");
			}
		} finally {
			try {
				manager.removeRepository(repositoryId);
			} finally {
				manager.shutDown();
				privateEndpoint.stop(0);
			}
		}
	}

