	private void assertUnapprovedLucenePluginIsNotLoaded(String key, String suffix) {
		String repositoryId = "managed-egress-unapproved-" + suffix;
		System.clearProperty(PLUGIN_INITIALIZED_PROPERTY);
		System.clearProperty(PLUGIN_CONSTRUCTED_PROPERTY);
		RemoteRepositoryManager manager = RemoteRepositoryManager.getInstance(TestServer.SERVER_URL);
		try {
			LuceneSailConfig lucene = new LuceneSailConfig("index", new MemoryStoreConfig());
			lucene.setParameter(key, UnapprovedConstructorProbe.class.getName());
			Throwable configFailure = catchThrowable(() -> manager.addRepositoryConfig(
					new RepositoryConfig(repositoryId, new SailRepositoryConfig(lucene))));
			if (configFailure == null) {
				HTTPRepository managed = new HTTPRepository(
						Protocol.getRepositoryLocation(TestServer.SERVER_URL, repositoryId));
				catchThrowable(() -> {
					try (RepositoryConnection connection = managed.getConnection()) {
						connection.size();
					}
				});
			}
			assertThat(System.getProperty(PLUGIN_INITIALIZED_PROPERTY)).isNull();
			assertThat(System.getProperty(PLUGIN_CONSTRUCTED_PROPERTY)).isNull();
			assertThat(configFailure).hasStackTraceContaining("unapproved repository configuration class");
		} finally {
			manager.removeRepository(repositoryId);
			manager.shutDown();
			System.clearProperty(PLUGIN_INITIALIZED_PROPERTY);
			System.clearProperty(PLUGIN_CONSTRUCTED_PROPERTY);
		}
	}

